import{_ as d,o as r,c as e,ag as o}from"./chunks/framework.DJVIMu25.js";const _=JSON.parse('{"title":"计分与事件","description":"","frontmatter":{"title":"计分与事件"},"headers":[],"relativePath":"zh_Hans/reference/scoring.md","filePath":"zh_Hans/reference/scoring.md","lastUpdated":1786543805000}'),a={name:"zh_Hans/reference/scoring.md"};function n(s,t,c,g,h,l){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="计分与事件" tabindex="-1">计分与事件 <a class="header-anchor" href="#计分与事件" aria-label="Permalink to &quot;计分与事件&quot;">​</a></h1><h2 id="游戏计分与特殊事件" tabindex="-1">游戏计分与特殊事件 <a class="header-anchor" href="#游戏计分与特殊事件" aria-label="Permalink to &quot;游戏计分与特殊事件&quot;">​</a></h2><p>每款游戏在游戏进行中会实时通过 <code>onScoreChange</code> 更新侧边栏计分板，并在达成里程碑时触发 <code>onGameEvent</code> 给予即时奖励。各游戏的玩法详见 <a href="./../guides/games">游戏模式</a>。</p><table tabindex="0"><thead><tr><th>游戏</th><th>计分规则</th><th>特殊事件奖励</th></tr></thead><tbody><tr><td><strong>2048</strong></td><td>每次合并 = 合并方块值之和</td><td>达成 2048 +50 代币</td></tr><tr><td><strong>扫雷</strong></td><td>每揭开 1 安全格 +10 分</td><td>触雷时播放受伤音效</td></tr><tr><td><strong>打地鼠</strong></td><td>击中 +1 分，3 连击额外 +2 分</td><td>击中黄金地鼠 +5 代币</td></tr><tr><td><strong>宝石迷阵</strong></td><td>消除 N 个宝石 N×10×连锁倍数</td><td>4+ 连锁每次 +N 代币</td></tr><tr><td><strong>彩票</strong></td><td>每次开奖消耗 1 张彩票（或代币）</td><td>奖项池随机奖励（代币/金币/命令）</td></tr><tr><td><strong>抽奖机</strong></td><td>每次抽奖消耗代币</td><td>三连相同 → 头奖奖项池；两连相同 → 固定代币</td></tr><tr><td><strong>迷宫</strong></td><td>通关用时（秒）越短分越高</td><td>通关基础 30 代币，每多 10 秒 -2 代币（最低 5）</td></tr><tr><td><strong>战舰</strong></td><td>击中 +100，击沉 +500</td><td>击沉奖励 = 船大小×5 代币</td></tr><tr><td><strong>四子棋</strong></td><td>每落子 +1，胜利时 4 分</td><td>形成 3 连威胁 +2 代币</td></tr><tr><td><strong>井字棋</strong></td><td>胜 +3，平 +1</td><td>形成 2 连威胁 +1 代币</td></tr><tr><td><strong>石头剪刀布</strong></td><td>胜 +2，平 +1</td><td>2 连胜 +2，3 连胜 +3 代币</td></tr><tr><td><strong>贪吃蛇</strong></td><td>每吃一个食物 +10 分</td><td>每 50 分里程碑 +1 代币</td></tr><tr><td><strong>小恐龙跑酷</strong></td><td>每存活 1 tick +1 分</td><td>每 50 分里程碑 +1 代币</td></tr><tr><td><strong>国际象棋</strong></td><td>胜 200 + 吃子价值×10，平 100 + 吃子价值×5</td><td>—</td></tr><tr><td><strong>大富翁</strong></td><td>胜 / 平 / 负 按结果结算</td><td>胜 +10、平 +3、负 +2 代币（3 人下注命中额外奖励）</td></tr></tbody></table><h2 id="placeholderapi-占位符" tabindex="-1">PlaceholderAPI 占位符 <a class="header-anchor" href="#placeholderapi-占位符" aria-label="Permalink to &quot;PlaceholderAPI 占位符&quot;">​</a></h2><p>挂钩 PlaceholderAPI 后可用以下占位符：</p><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th></tr></thead><tbody><tr><td><code>%gamebox_tokens%</code></td><td>当前玩家代币余额</td></tr><tr><td><code>%gamebox_highscore_&lt;id&gt;%</code></td><td>当前玩家在某游戏的最高分（如 <code>%gamebox_highscore_2048%</code>）</td></tr><tr><td><code>%gamebox_ingame%</code></td><td>当前玩家是否在游戏中（true/false）</td></tr></tbody></table>',7)])])}const b=d(a,[["render",n]]);export{_ as __pageData,b as default};
